"""Metadata processing for report-ledger."""

import json
from datetime import date


def _validate_row(row):
    if not isinstance(row, dict):
        raise ValueError('row must be an object')

    tenant = row.get('tenant')
    if not isinstance(tenant, str) or not tenant:
        raise ValueError('tenant must be a nonempty string')

    amount = row.get('amount_cents')
    if not isinstance(amount, int) or isinstance(amount, bool):
        raise ValueError('amount_cents must be an integer')

    day = row.get('day')
    if not isinstance(day, str):
        raise ValueError('day must be a string')
    try:
        parsed = date.fromisoformat(day)
    except ValueError:
        raise ValueError('day must be a valid YYYY-MM-DD date')
    if parsed.isoformat() != day:
        raise ValueError('day must be a valid YYYY-MM-DD date')

    return amount, day


def summarize_rows(text: str):
    """Parse a JSON array of rows. Each row has a nonempty string tenant, an integer
    amount_cents (negative amounts are allowed; booleans are invalid), and a valid YYYY-
    MM-DD string day. Return row_count, total_cents, first_day, and last_day. Empty
    input gives zero totals and null dates. Ignore extra fields. Raise ValueError on
    malformed JSON or rows."""
    try:
        rows = json.loads(text)
    except (ValueError, TypeError):
        raise ValueError('malformed JSON input')

    if not isinstance(rows, list):
        raise ValueError('input must be a JSON array of rows')

    total_cents = 0
    days = []
    for row in rows:
        amount, day = _validate_row(row)
        total_cents += amount
        days.append(day)

    return {
        'row_count': len(rows),
        'total_cents': total_cents,
        'first_day': min(days) if days else None,
        'last_day': max(days) if days else None,
    }
